pub struct AccessDigestResultSentItem {
    pub tenant_id: String,
    pub recipients: f64,
    pub expiring_identities: f64,
    pub expiring_bindings: f64,
    pub starting_bindings: f64,
    pub expiring_memberships: f64,
    pub activations: f64,
    pub pending_requests: f64,
    pub unused_keys: f64,
    pub expiring_keys: f64,
}

#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccessDigestResultSkipped {
    pub inactive: f64,
    pub recent: f64,
    pub quiet: f64,
    pub no_owners: f64,
}

#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ExpiryReminderResult {
    /// One entry per person emailed, with how many of their items end within the window.
    pub sent: Vec<ExpiryReminderResultSentItem>,
    /// Tenants left alone: not active, or with nothing new to remind anyone about.
    pub skipped: ExpiryReminderResultSkipped,
}

#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ExpiryReminderResultSentItem {
    pub tenant_id: String,
    pub identity_id: String,
    pub items: f64,
}

#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ExpiryReminderResultSkipped {
    pub inactive: f64,
    pub quiet: f64,
}

#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SweepOptions {
    /// Epoch milliseconds to treat as now, for tests and backfills. By default each collection is
    /// judged by the clock its writer uses: the authentication clock for sessions, devices,
    /// relationships, the outbox, and audit hooks, and the wall clock for OAuth, SAML, and SSF records.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub now: Option<f64>,
    /// Records read per transaction (default 500, 1-5000). Short transactions keep the write lock brief.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub batch_size: Option<f64>,
    /// The most records one run deletes (default 10000, at most 1000000); see `truncated`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub limit: Option<f64>,
    /// How long delivered and abandoned deliveries stay (outbox email, SMS, and webhook history, failed
    /// Shared Signals deliveries): default 30 days, 0-3650 days. Pending deliveries are never swept.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub delivery_retention_ms: Option<f64>,
    /// A margin past expiry before a record is deleted, against clock skew between instances (default 5 minutes, at most 1 day).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub grace_ms: Option<f64>,
}

#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SweepResult {
    /// Records deleted per collection; collections with nothing to delete are omitted.
    pub deleted: indexmap::IndexMap<String, f64>,
    pub total: f64,
    /// The run stopped at `limit` before finishing; more records may be due, so run it again.
    pub truncated: bool,
}

#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ProtocolService {
    pub base_path: String,
    /// Function (not serializable)
    #[serde(
        default,
        skip_serializing_if = "Option::is_none",
        with = "crate::runtime::present"
    )]
    pub handler: Option<serde_json::Value>,
    /// Function (not serializable)
    #[serde(
        default,
        skip_serializing_if = "Option::is_none",
        with = "crate::runtime::present"
    )]
    pub node_handler: Option<serde_json::Value>,
}

#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ErrorEnvelope {
    pub error: ErrorEnvelopeError,
}

#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ErrorEnvelopeError {
    /// Stable error code, for example ACCESS_DENIED.
    pub code: String,
    /// Human-readable explanation; may change between releases.
    pub message: String,
    /// Present on RATE_LIMITED.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub retry_after_ms: Option<f64>,
}
